              },
              "direction": {
                "enum": [
                  "L",
                  "R"
                ]
              }
            },
            "required": [
              "kind"
            ],
            "additionalProperties": false
          },
          "minItems": 1
        },
        "start": {
          "type": "array",
          "items": {
            "type": "number"
          },
          "minItems": 2,
          "maxItems": 2,
          "description": "BEGIN, where legs start: [x, y] = [easting, northing]"
        },
        "legs": {
          "type": "array",
          "items": {
            "type": [
              "object",
              "string"
            ],
            "description": "one tangent, from one PI to the next: a direction (exactly one of bearing, azimuth, deflection, angle_right) and the distance to the next PI; radius is the curve at the PI where this leg starts (a leg after the first). Or as text: \"S 76°15'00\\\" E 650\", \"33 L 820 R=450\"",
            "properties": {
              "bearing": {
                "type": "string",
                "description": "quadrant bearing: N 47°30'15\" E, S47-30-15W, N47E"
              },
              "azimuth": {
                "type": [
                  "number",
                  "string"
                ],
                "description": "degrees clockwise from north, 0-360"
              },
              "deflection": {
                "type": [
                  "number",
                  "string"
                ],
                "description": "the angle the alignment turns at the PI where this leg starts: '33 L', '18°30'00\" RT', or a number with right positive; or its size with turn"
              },
              "turn": {
                "type": "string",
                "enum": [
                  "left",
                  "right",
                  "L",
                  "R"
                ],
                "description": "which way a deflection turns"
              },
              "angle_right": {
                "type": [
                  "number",
                  "string"
                ],
                "description": "angle clockwise from the backsight"
              },
              "distance": {
                "type": "number",
                "exclusiveMinimum": 0,
                "description": "feet from this leg's PI to the next PI"
              },
              "radius": {
                "type": "number",
                "minimum": 0,
                "description": "the curve at the PI where this leg starts (0 or omitted: none, which needs angle_points)"
              }
            },
            "additionalProperties": false
          },
          "minItems": 1,
          "description": "the layout as bearings and distances, PI to PI from start -- as a report describes it: 'S 76° E 650 ft to PI-2, where it deflects 33° left on a 450 ft curve; then 820 ft...' is [{bearing: 'S 76 E', distance: 650}, {deflection: '33 L', radius: 450, distance: 820}, ...]"
        },
        "begin_station": {
          "type": [
            "number",
            "string"
          ],
          "description": "display station: feet (8400) or '84+00.00'"
        },
        "equations": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "back": {
                "type": [
                  "number",
                  "string"
                ],
                "description": "display station: feet (8400) or '84+00.00'"
              },
              "ahead": {
                "type": [
                  "number",
                  "string"
                ],
                "description": "display station: feet (8400) or '84+00.00'"
              },
              "raw_station": {
                "type": "number"
              }
            },
            "required": [
              "back",
              "ahead"
            ],
            "additionalProperties": false
          }
        },
        "description": {
          "type": "string"
        },
        "angle_points": {
          "type": "boolean",
          "description": "allow interior PIs of radius 0: angle points, where the tangents meet with no curve -- a layout whose curves come later (default false: a missing radius is refused)"
        }
      },
      "required": [
        "name"
      ],
      "additionalProperties": false
    },
